    "atomId": "ACI-P086-L012-3BB77976D7-04",
    "semanticOwnerId": "classical-object-relationship-analysis",
    "canvasSection": "§7.9.2.b",
    "canvasSpan": "3262–3263",
    "statement": "Qu-Ø in niquitta realizes a specific third-person common-or-singular nonhuman object.",
