    "atomId": "ACI-P086-L012-3BB77976D7-05",
    "semanticOwnerId": "classical-object-relationship-analysis",
    "canvasSection": "§7.9.2.b",
    "canvasSpan": "3262–3263",
    "statement": "With a singular animate nonhuman object, niquitta means ‘I see it.’",
