    "semanticOwnerId": "classical-adverbial-adjunction-condition-vnc-center",
    "canvasSection": "§50.7.1.b",
    "canvasSpan": "21573–21574",
    "statement": "When the adverbial-adjunct VNC is present indicative, the condition is presented as purely neutral.",
    "projectRole": "read-only-grammar-fact",
