    "semanticOwnerId": "classical-denominal-vnc-ya-root-rank-source",
    "canvasSection": "§54.2.3.a",
    "canvasSpan": "23145–23148",
    "statement": "The verbstem (huē-i-ya-Ø-qu-i-ya) means ‘to become long.’",
    "projectRole": "read-only-grammar-fact",
