    "semanticOwnerId": "classical-late-grammar-nonspecific-subject-specific-supplement",
    "canvasSection": "§57.4.3.a",
    "canvasSpan": "24868",
    "statement": "A principal VNC whose nonspecific subject takes a specific supplementary subject is in the impersonal voice.",
    "projectRole": "read-only-grammar-fact",
