    "semanticOwnerId": "classical-late-grammar-silent-first-person",
    "canvasSection": "§57.6",
    "canvasSpan": "24971–24975",
    "statement": "Tinehuihuīcān tlamatizqueh, āc yeh tlani huetziz means ‘let us have a contest to see which one will lose.’",
    "projectRole": "read-only-grammar-fact",
    "contentFingerprint": "fnv1a32:c5dd7f37"
