    "semanticOwnerId": "classical-late-grammar-matrix-object-control",
    "canvasSection": "§58.2.4",
    "canvasSpan": "25155–25159",
    "statement": "The grain-bin, maize-crib, and box examples are nonexhaustive and do not restrict the productive indefinite nonhuman object domain.",
    "projectRole": "read-only-grammar-fact",
    "contentFingerprint": "fnv1a32:65652493"
