function deepFreeze(value) {
  if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) deepFreeze(child);
  return freeze(value);
}

export function fingerprintClassicalCanvasGrammarFact(record = {}) {
  let hash = 0x811c9dc5;
  const text = [record.atomId, record.semanticOwnerId, record.canvasSection, record.canvasSpan, record.statement, record.projectRole].join("\u241f").normalize("NFC");
  for (const symbol of text) { hash ^= symbol.codePointAt(0); hash = Math.imul(hash, 0x01000193) >>> 0; }
  return `fnv1a32:${hash.toString(16).padStart(8, "0")}`;
}

const RECORDS = deepFreeze(records);
const BY_ATOM_ID = new Map(RECORDS.map((record) => [record.atomId, record]));

export function isClassicalCanvasGrammarFactRecord(record = null) {
  return Boolean(record && record.projectRole === "read-only-grammar-fact" && record.contentFingerprint === fingerprintClassicalCanvasGrammarFact(record));
}

export function getClassicalCanvasGrammarFactRecord(atomId = "") {
  return BY_ATOM_ID.get(String(atomId)) || null;
}

export function listClassicalCanvasGrammarFactRecords() { return RECORDS; }
